import{_ as s,l as n,o as i,c as t,v as r,p as l,x as e,d as p,i as m,S as h}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"Dispersion 交易","description":"","frontmatter":{"title":"Dispersion 交易","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/dispersion-trade.md","filePath":"quant/dispersion-trade.md","lastUpdated":1789023840000}'),_={name:"quant/dispersion-trade.md"};function d(E,a,A,u,B,g){const o=n("Mermaid");return i(),t("div",null,[a[1]||(a[1]=r('<h1 id="dispersion-交易" tabindex="-1">Dispersion 交易 <a class="header-anchor" href="#dispersion-交易" aria-label="Permalink to &quot;Dispersion 交易&quot;">​</a></h1><div class="epigraph"><p>指数方差小于成分股方差的加权平方和，差额由两两相关填满；卖出指数波动、买入一篮子个股波动，押的是隐含相关高于随后实现的相关，而不是押「指数期权更贵」这一句空话。</p><footer>—— Driessen, Maenhout and Vilkov, The Price of Correlation Risk, Journal of Finance, 2009；方差分解为指数期权文献的标准恒等式</footer></div><p>指数收益是成分的加权和。方差恒等式把指数方差拆成特质块与相关块：</p> \\[\\sigma_I^2=\\sum_i w_i^2\\sigma_i^2+\\sum_{i\\neq j}w_i w_j\\rho_{ij}\\sigma_i\\sigma_j. \\]<p>期权市场同时给 \\(\\sigma_I\\)（指数隐含）与 \\(\\sigma_i\\)（个股隐含），于是可以反解一个隐含相关 \\(\\rho_{\\mathrm{impl}}\\)。Joost Driessen、Pascal Maenhout 与 Grigory Vilkov（2009）表明：指数期权所隐含的相关，平均高于随后已实现相关——相关作为风险因子被定价，因为危机里股票一起跌，见 <a href="/quant/correlation-breakdown">相关性崩溃</a>。Dispersion 交易就是把这笔溢价做成可交易腿：通常短指数方差、长成分方差，权重使 Delta 与净 Vega 按设计对冲。本篇写隐含相关的定义、复制与基差，不把单名 <a href="/quant/vol-arb">波动率套利</a> 再讲一遍，也不把 DCC 的动态相关当成交易信号。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若所有 \\(\\rho_{ij}=\\rho\\)，且忽略对角的 \\(w_i^2\\) 项（大篮子下较小），则</p> \\[\\rho_{\\mathrm{impl}}\\approx\\frac{\\sigma_I^2-\\sum_i w_i^2\\sigma_i^2}{\\bigl(\\sum_i w_i\\sigma_i\\bigr)^2-\\sum_i w_i^2\\sigma_i^2}. \\]<p>CBOE 一类隐含相关指数用上市期权与指数权重做离散版。问题是：\\(\\sigma_I\\) 与 \\(\\sigma_i\\) 必须是同一对象——期限对齐、都用方差（或都用 ATM 波动并承认偏差）、都尽量接近 <a href="/quant/var-swap-replication">条带复制</a> 而不是随意一个 Delta。用指数 VIX、个股 ATM IV，得到的 \\(\\rho\\) 混进了微笑差异：指数偏斜通常陡于平均个股，条带方差比 ATM 更能代表恒等式里的 \\(\\sigma^2\\)。</p><p>交易上还有权重与容量。成分有数百只，不可能每只都买方差互换；实务用前 \\(N\\) 大权重、或用行业 ETF 期权代替尾部。截断使你实际交易的是「可交易子集上的相关」，与指数官方权重不同，基差在成分股特有事件（单名财报跳）时放大。问题收成：如何定义 \\(\\rho_{\\mathrm{impl}}\\)、如何用有限的个股腿去近似恒等式的多头，以及溢价在何种压力下会反向支付。</p><h3 id="隐含相关不是已实现相关的预测" tabindex="-1">隐含相关不是已实现相关的预测 <a class="header-anchor" href="#隐含相关不是已实现相关的预测" aria-label="Permalink to &quot;隐含相关不是已实现相关的预测&quot;">​</a></h3><p>\\(\\rho_{\\mathrm{impl}}\\) 在风险中性下，含相关风险溢价与跳共跳。已实现相关在物理测度下，用收益窗口估计，还受 Forbes–Rigobon 异方差影响：波动上升时样本相关会变高，即使依赖结构不变。Driessen–Maenhout–Vilkov 把指数期权相对个股期权的贵，归因于投资者厌恶相关上升的状态——分散化在最需要时失效，愿意为「指数式」保险付费。把 \\(\\rho_{\\mathrm{impl}}-\\rho_{\\mathrm{RV}}\\) 当成预测误差去择时，会把溢价写成 alpha。正确的零假设是溢价为正（隐含高于实现），策略赚的是这份保险费，在相关崩溃日偿还。</p><p><span class="marginnote">等权相关与市值加权相关不是同一个数。指数方差恒等式里的 \\(\\rho\\) 是以 \\(w_i\\sigma_i\\) 为权重的；对所有股票对做等权平均，会夸大小盘股，与指数期权对不上。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><strong>腿的构造。</strong> 空头：指数方差互换、VIX 期货、或 Delta 对冲的指数跨式/条带。多头：成分股方差互换（稀）或 Delta 对冲的个股跨式，权重正比于 \\(w_i\\) 或 \\(w_i\\sigma_i\\)，使一阶上对冲指数方差里的特质项。净 Vega 应接近对 \\(\\rho\\) 的暴露：指数 Vega 为负、个股 Vega 为正，比例使「全体 IV 平行上移」的 PnL 接近零，只对相关敏感。做不到完全平行——指数微笑与个股微笑的期限、翼部不同，残差应单独限额。</p><p><strong>对冲清单。</strong> Delta：各腿自己对冲标的，指数腿对冲指数、个股腿对冲个股，不要用指数期货去「代替」一篮子个股 Delta，否则成分相对指数的残差会冒充 dispersion。Gamma：指数与个股的 Gamma 剖面不同，现货大动时净 Gamma 会漂，需再平衡或用方差互换减少路径依赖。借券与分红：个股多头期权遇事件，提前行权与借券费进入成本，指数腿没有对称项。</p><p><strong>样本与容量。</strong> 只在有上市期权、价差可接受的名字上建多头，尾部权重并入「不可交易残差」。权重再平衡随指数调整与波动变化，频率过高则手续费吃掉溢价。危机里个股期权买卖价差先于指数爆炸，多头腿无法加仓或平仓，实际变成裸空指数波动——这是策略的真实风险，不是电子表上的 \\(\\rho\\) 缺口。</p><h3 id="从方差互换到相关互换" tabindex="-1">从方差互换到相关互换 <a class="header-anchor" href="#从方差互换到相关互换" aria-label="Permalink to &quot;从方差互换到相关互换&quot;">​</a></h3><p>若能交易全部单名与指数的方差互换，组合</p> \\[\\sum_{i\\neq j} w_i w_j \\sigma_i\\sigma_j\\,\\rho_{ij} \\]<p>的浮动腿接近指数方差减加权单名方差。这是相关互换的离散实现。市场很少直接报相关互换，dispersion 是它的期权近似。Bossu 等把方差互换账上的 dispersion 写成交易员算法；学术上 DMV 用期权收益与复制组合检验溢价是否显著、是否被市场因子解释。检验应同时报告：平均 \\(\\rho_{\\mathrm{impl}}-\\rho_{\\mathrm{RV}}\\)、空指数—多个股组合的平均 PnL、以及控制股票市场、VIX 水平之后是否还有残差——否则只是又在卖指数方差。</p>',21)),(i(),l(h,null,{default:e(()=>[m(o,{id:"mermaid-55",class:"mermaid",graph:"flowchart%20TD%0A%20%20Idx%5B%22%E6%8C%87%E6%95%B0%E9%9A%90%E5%90%AB%E6%96%B9%E5%B7%AE%20%CF%83_I%C2%B2%22%5D%20--%3E%20Rho%5B%22%E5%8F%8D%E8%A7%A3%20%CF%81_impl%22%5D%0A%20%20Stk%5B%22%E6%88%90%E5%88%86%E9%9A%90%E5%90%AB%E6%96%B9%E5%B7%AE%20%CF%83_i%22%5D%20--%3E%20Rho%0A%20%20W%5B%22%E6%8C%87%E6%95%B0%E6%9D%83%E9%87%8D%20w_i%22%5D%20--%3E%20Rho%0A%20%20Rho%20--%3E%20Short%5B%22%E7%A9%BA%E6%8C%87%E6%95%B0%E6%B3%A2%E5%8A%A8%22%5D%0A%20%20Rho%20--%3E%20Long%5B%22%E5%A4%9A%E4%B8%AA%E8%82%A1%E6%B3%A2%E5%8A%A8%E7%AF%AE%E5%AD%90%22%5D%0A%20%20Short%20--%3E%20Disp%5B%22Dispersion%20%E7%BB%84%E5%90%88%22%5D%0A%20%20Long%20--%3E%20Disp%0A%20%20CR%5B%22%E7%9B%B8%E5%85%B3%E5%B4%A9%E6%BA%83%22%5D%20--%3E%20Pay%5B%22%E7%A9%BA%E5%A4%B4%E8%85%BF%E8%B5%94%E4%BB%98%22%5D%0A%20%20Disp%20--%3E%20Prem%5B%22%E8%B5%9A%E9%9A%90%E5%90%AB%E5%87%8F%E5%AE%9E%E7%8E%B0%E7%9B%B8%E5%85%B3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>指数期权提供的是对共同因子的保险：买一张指数虚值看跌，覆盖的是「许多股票一起跌」。买一篮子个股看跌，覆盖的是各名字自己的跳，对共跳的对冲效率低、成本高。二者价差因此含相关溢价。危机里杠杆与流动性把股票赶进同一条卖出通道，实现相关上升，dispersion 空头（指数）损失大于个股多头的收益——因为指数方差里相关项被平方放大，而你持有的个股腿往往来不及按官方权重配齐、且价差已经拉开。这与「个股波动也升了所以多头该赚钱」不矛盾：两边都升，但相关项使指数升得更多。</p><p>与单名 vol arb 的差别：单名赌 \\(\\mathrm{IV}_i\\) 对 \\(\\mathrm{RV}_i\\)；dispersion 在一阶上把平均 vol 对冲掉，赌 \\(\\rho\\)。实现上对冲不会完美，账里仍有净方差暴露，归因必须做：把 PnL 回归到指数 RV、平均个股 RV、以及实现相关，看第三项是否真的在赚钱。若第一项主导，你只是在做指数 vol arb，却付了个股腿的价差。</p><h3 id="权重截断与行业替代" tabindex="-1">权重截断与行业替代 <a class="header-anchor" href="#权重截断与行业替代" aria-label="Permalink to &quot;权重截断与行业替代&quot;">​</a></h3><p>用行业 ETF 期权代替一篮子小权重股票，相关对象变成「指数对行业」加上「行业内部」，与官方 \\(\\rho\\) 不同。行业内部相关在危机同样上升，ETF 腿会部分对冲指数空头，削弱溢价也削弱回撤。这是容量与纯度的权衡。另一种截断是只做流动性最好的二十只：指数里的其余成分变成基差。财报季这些名字的特质跳会让个股多头赚钱、指数不动，看起来像 dispersion 大胜，其实是事件风险，样本外不可重复。</p><p><span class="marginnote">隐含相关对「全体个股 IV 平行乘一个因子」敏感。个股做市商集体把翼部标高时，\\(\\rho_{\\mathrm{impl}}\\) 会下降（分母变大），并不等于市场在卖相关。应同时看 \\(\\sigma_I\\) 与 \\(\\sum w_i\\sigma_i\\) 的水平。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>恒等式是方差的，不是波动率的。用 ATM IV 代替 \\(\\sigma\\) 会留下 Jensen 与微笑误差。期限必须一致：指数用三十天、个股用当周，相关没有定义。美式个股、欧式指数，早行权溢价进入 \\(\\sigma_i\\)。指数调整、停牌、成分跳进跳出，使权重 \\(w_i\\) 与期权上市不同步。跨国指数的个股期权散落在不同交易所，时区使「同一时刻的 \\(\\rho\\)」是幻象。</p><p>Driessen–Maenhout–Vilkov（2009）是相关风险价格的关键证据；CBOE 隐含相关指数是操作定义；Brunnermeier 一类流动性螺旋解释为何实现相关会在空头最痛时上升。不要把 dispersion 写成 1994 年 Dupire 的应用，也不要写成统计套利：它是期权市场的保险卖出。A 股若指数期权与个股期权深度不对称，多头腿无法建立，策略退化为卖指数波动，应直接按 vol arb 风控，而不是报一个无法交易的 \\(\\rho_{\\mathrm{impl}}\\)。</p><p><span class="marginnote">相关崩溃篇写的是现货收益的依赖结构；本篇写的是期权如何给这个结构定价。用现货滚动相关去择时 dispersion，漏掉了隐含腿已经包含的溢价。</span></p><p><span class="marginnote">净 Vega 为零的当日，并不保证对 vol-of-vol 或偏斜为零。指数与个股的 Vanna 不同，现货跳后净暴露会从「纯相关」变成「净空指数尾」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>指数方差减加权个股方差，定义隐含相关；dispersion 卖出该相关的保险。</li><li>构造上短指数波动、长可交易成分波动，目标是对冲平均 vol、留下 \\(\\rho\\)。</li><li>溢价平均为正（DMV），在相关崩溃日偿还；不是无风险套利。</li><li>对象须用对齐期限的方差（条带优于 ATM）；截断权重与价差构成基差。</li><li>归因要分离指数 RV、个股 RV 与实现相关，避免把指数 vol arb 误报成 dispersion。</li><li>出处：Driessen, Maenhout and Vilkov, <em>Journal of Finance</em>, 2009；复制恒等式见 Carr and Madan；危机相关见 Longin–Solnik、Ang–Chen。</li></ul>',13))])}const V=s(_,[["render",d]]);export{D as __pageData,V as default};
